<?php
defined('WB_PATH')or die('No direct access');if(!function_exists('wbce_add_filter')||!function_exists('wbce_add_action')){$captchaPhpBridge=WB_PATH.'/modules/wbce_hook_bridge/preinit.php';if(is_file($captchaPhpBridge))require_once $captchaPhpBridge;}if(!function_exists('wbce_add_filter')||!function_exists('wbce_add_action'))return;if(defined('WBCE_CAPTCHA_PROVIDER_PHPCAPCHA_REGISTERED'))return;define('WBCE_CAPTCHA_PROVIDER_PHPCAPCHA_REGISTERED',true);if((string)Settings::Get('captcha_phpcapcha_installed','')!=='1')return;
require_once __DIR__.'/Provider.php';require_once WB_PATH.'/modules/captcha_control/ProviderUi.php';$captchaPhpText=WbceCaptchaProviderUi::language(__DIR__,array());
wbce_add_filter('captcha.providers',function($providers)use($captchaPhpText){if(extension_loaded('gd')&&function_exists('imagepng'))$providers['phpcapcha']=array('name'=>$captchaPhpText['name'],'description'=>$captchaPhpText['description'],'module'=>'captcha_phpcapcha','render'=>array('WbcePhpcapchaProvider','render'),'verify'=>array('WbcePhpcapchaProvider','verify'));return $providers;});
wbce_add_filter('captcha.settings.sections',function($sections,$selected)use($captchaPhpText){if($selected!=='phpcapcha')return $sections;$content=WbceCaptchaProviderUi::row($captchaPhpText['length'],WbceCaptchaProviderUi::input('number','captcha_phpcapcha_length',(int)Settings::Get('captcha_phpcapcha_length',6),array('min'=>'4','max'=>'8'))).WbceCaptchaProviderUi::row($captchaPhpText['timeout'],WbceCaptchaProviderUi::input('number','captcha_phpcapcha_timeout',(int)Settings::Get('captcha_phpcapcha_timeout',600),array('min'=>'60','max'=>'3600')));$sections[]=WbceCaptchaProviderUi::fieldset($captchaPhpText['configure'],$content);return $sections;});
wbce_add_action('captcha.settings.save',function($input,$selected){if($selected!=='phpcapcha')return;$rawLength=$input['captcha_phpcapcha_length']??6;$rawTimeout=$input['captcha_phpcapcha_timeout']??600;$length=is_scalar($rawLength)?(int)$rawLength:6;$timeout=is_scalar($rawTimeout)?(int)$rawTimeout:600;$errors=array(Settings::Set('captcha_phpcapcha_length',(string)max(4,min(8,$length))),Settings::Set('captcha_phpcapcha_timeout',(string)max(60,min(3600,$timeout))));foreach($errors as $error)if($error)throw new RuntimeException((string)$error);});
